"""Separate actual anchor bulk, pressure-cell and external-trace contrasts."""
import sys,json,shutil
import numpy as np
from baseline_registry import ROOT,ref,dump

def main():
 out=ROOT/'validation/integrated'/sys.argv[1];out.mkdir(exist_ok=False);shutil.copyfile(__file__,out/'reviewer.py');tags=sys.argv[2:];docs=[json.loads((ROOT/'validation/integrated'/t/'summary.json').read_text()) for t in tags];sources=[ref(ROOT/'validation/integrated'/t/'summary.json') for t in tags];a,b,c=docs[:3];comparisons=[]
 for label,x,y,sx,sy in [('bulk_mesh_fixed_actual_source_and_cells',a,b,sources[0],sources[1]),('contact_cell_divisions_fixed_bulk_and_source',a,c,sources[0],sources[2])]:
  rows=[]
  for r,t in zip(x['rows'],y['rows']):
   assert r['case']==t['case'];wa=r.get('total_strain_work_Nmm');wb=t.get('total_strain_work_Nmm')
   if wa is None or wb is None:rows.append(dict(case=r['case'],qualified=False,reason='missing numerical solution'));continue
   e=abs(wb/wa-1);peak=abs(max(t['pressures_MPa'])/max(r['pressures_MPa'])-1);bolt=float(np.linalg.norm(np.array(r['bolt_tension_N'])-t['bolt_tension_N'])/max(np.linalg.norm(t['bolt_tension_N']),1e-30));rows.append(dict(case=r['case'],relative_conditional_work_change=e,relative_peak_pressure_change=peak,relative_bolt_vector_change=bolt,original1percent_all_response=e<.01 and peak<.01 and bolt<.01))
  comparisons.append(dict(variable=label,sources=[sx,sy],rows=rows,all14_original1percent=all(r.get('original1percent_all_response',False) for r in rows),largest_conditional_work_change=max(r['relative_conditional_work_change'] for r in rows)))
 nominal=[dict(source=s,conditional_test_work_Nmm=d['rows'][0]['total_strain_work_Nmm'],bolt_tension_N=d['rows'][0]['bolt_tension_N'],peak_cell_pressure_MPa=max(d['rows'][0]['pressures_MPa']),body_elastic_displacement_mm=[r['maximum_elastic_displacement_mm'] for r in d['rows'][0]['full_body_equilibrium']]) for s,d in zip(sources,docs)]
 dump(out/'summary.json',dict(status='ACTUAL_P1_FINITE_ELASTIC_CONTACT_CONVERGENCE_FAIL',candidate=a['candidate'],reviewer=ref(out/'reviewer.py'),sources=sources,comparisons=comparisons,nominal_conditional_tests=nominal,accepted_actual_product_equilibria=0,newly_qualified_system_gate_ids=[],whole_system_release=False,strategy_review=[dict(option='A',mechanism='SAME actual P1: common-refinement finite contact traces with local active pressure refinement and memory-efficient six-gauge finite-body solve; replace nominal major-envelope branches with source-backed finite head/nut/thread/rest stack',decision='NEXT_MECHANISM',blockers='Source-backed material minima/rest/preload and real external receiver interface still absent;must not convert contact average PASS into actual gap PASS.'),dict(option='B',mechanism='Add actual source-dimensional external receiver bracket/bench-clamp geometry and finite support compliance before operating-load claims',decision='REQUIRED_PHYSICAL_SUPPORT_CONTINUATION',blockers='External support dimensions/material/clamp/preload are not currently evidence;no arbitrary fixation or signed trace may stand in for this.'),dict(option='C',mechanism='Reuse old rigid LP or fix receiver/Root and report successful global support',decision='REJECTED',blockers='Violates actual finite load path,source identity,existing convergence/contact/energy criteria. No physical external attachment;all historical failures remain.' )],limitations=['All results are actual full-body conditional sensitivities,not strength,rated loads,globalstoredenergy or performance rewards.','Conditional positive cell force/average complementarity is not pointwise physical contact.','Bulk mesh remains mixed with linear curved-hole boundary approximation;exact same source field and pressure partition are independently audited.','Historical affine-source triangle-selection failure is excluded from these fixed-source comparisons;retained separately.']))
 print(json.dumps(dict(work_changes=[r['largest_conditional_work_change'] for r in comparisons],all14=[r['all14_original1percent'] for r in comparisons])))
